'use strict';
const $ = id => document.getElementById(id);
const esc = value => String(value).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fmt = n => Number(n).toLocaleString('ko-KR');
const regions = {
  '전국': {metrics:[25425,59613,2075456],districts:[['안산시',55713],['창원시',43021],['전주시',42926],['김해시',41580],['청주시',37696]],sports:[['태권도',1055064],['기타종목',138745],['합기도',131239],['헬스',98655],['복싱',88310]]},
  '서울': {metrics:[1820,4530,268400],districts:[['송파구',25823],['강북구',19676],['강동구',17897],['중랑구',15385],['강서구',15317]],sports:[['태권도',112000],['수영',38000],['농구',24000],['헬스',18000],['배드민턴',16000]]},
  '경기': {metrics:[4600,10800,532100],districts:[['안산시',55713],['고양시',28545],['남양주시',23719],['파주시',23228],['성남시',22870]],sports:[['태권도',245000],['수영',66000],['농구',37000],['헬스',32000],['배드민턴',28000]]},
  '부산': {metrics:[1450,3210,175000],districts:[['사하구',19326],['해운대구',17240],['북구',15148],['부산진구',14580],['동래구',12372]],sports:[['태권도',83000],['수영',28000],['농구',19000],['헬스',15000],['배드민턴',10000]]}
};
const facilityBase = [
  {id:'a',name:'한빛 생활체육센터',district:'중앙동',photo:0,sports:['농구','수영'],basis:'종목 시설유형 확인'},
  {id:'b',name:'늘봄 다목적체육관',district:'새빛동',photo:3,sports:['농구','태권도'],basis:'등록 프로그램 이력 확인'},
  {id:'c',name:'푸른 실내체육센터',district:'푸른동',photo:9,sports:['농구'],basis:'종목 시설유형 확인'},
  {id:'d',name:'누리 스포츠센터',district:'누리동',photo:2,sports:['수영','태권도'],basis:'등록 프로그램 이력 확인'}
];
let region='전국',sport='',selected=new Set(),confirmed=[],started=false,activeResult=null,map=null,geo=null;
const photo = f => '../../image/center/center'+f.photo+'.jpg';
function toast(text){$('notice').textContent=text;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('notice').textContent='',4500);}
function bars(values){const max=Math.max(...values.map(x=>x[1]));return values.map(([name,n])=>`<div class="bar"><div><span>${esc(name)}</span><span>${fmt(n)}</span></div><div class="track"><i style="width:${n/max*100}%"></i></div></div>`).join('');}
function drawMap(){if(!geo||!map)return;const aliases={'서울특별시':'서울','경기도':'경기','부산광역시':'부산'};const data=geo.features.map(f=>({name:f.properties.name,value:regions[aliases[f.properties.name]]?.metrics[2]||0,itemStyle:{areaColor:aliases[f.properties.name]===region?'#0064ff':undefined}}));map.setOption({tooltip:{formatter:p=>`${esc(p.name)}${aliases[p.name]?' · 클릭하여 선택':' · 시안 미지원 지역'}`},series:[{type:'map',map:'review-provinces',roam:false,layoutCenter:['50%','50%'],layoutSize:'97%',itemStyle:{areaColor:'#dbeaff',borderColor:'#fff'},emphasis:{itemStyle:{areaColor:'#7dbaff'},label:{show:true}},label:{show:false},data}]});map.off('click');map.on('click',p=>{if(aliases[p.name])setRegion(aliases[p.name]);else toast('시안에서는 서울·경기·부산을 선택할 수 있습니다.');});}
function refreshDashboard(){const d=regions[region];$('region').value=region;$('region-heading').textContent=region;$('metrics').innerHTML=['이용 시설','개설 강좌','신청인원 합계','관측 개설연월'].map((label,i)=>`<div class="metric"><small>${label}</small><strong>${i<3?fmt(d.metrics[i]):'2020.01 – 2026.08'}</strong><small>${['개 · 자료에 기록된 시설','건 · 시설·강좌 기준','명 · 고유 이용자 아님','조회 자료 기준 · 시안 예시'][i]}</small></div>`).join('');$('district-bars').innerHTML=bars(d.districts);$('sport-bars').innerHTML=bars(d.sports);$('start').disabled=region==='전국';$('start-help').textContent=region==='전국'?'먼저 설계할 지역을 선택하세요.':region+'의 현황을 참고해 설계를 시작합니다.';document.querySelectorAll('[data-region]').forEach(b=>b.classList.toggle('active',b.dataset.region===region));drawMap();}
function stage(n){document.body.dataset.step=n;$('change-region').hidden=n===0;$('overview').hidden=n!==0;$('builder').hidden=n===0;document.querySelectorAll('.steps span').forEach((s,i)=>{s.classList.toggle('current',i===n);s.classList.toggle('complete',i<n);});if(n===0)map?.resize();}
function setRegion(value){if(value===region)return;const had=selected.size||confirmed.length;region=value;selected.clear();confirmed=[];sport='';$('sport').value='';$('candidates').hidden=true;$('confirmed').hidden=true;$('details').hidden=true;$('builder').hidden=!started||region==='전국';$('selection-scope').textContent=region;stage(0);refreshDashboard();if(had)toast('지역이 변경되어 시설 선택을 해제했습니다. 프로그램 입력 내용은 유지됩니다.');}
function candidates(){return facilityBase.filter(f=>f.sports.includes(sport));}
let inspectedFacility=null;
function updateSelection(){
  $('selection-count').textContent=selected.size+'개 시설 선택';$('confirm').disabled=!selected.size;
  document.querySelectorAll('#facility-list input').forEach(input=>{input.checked=selected.has(input.value);});
  if($('detail-check'))$('detail-check').checked=selected.has(inspectedFacility);
}
function inspectCandidate(id){
  const f=candidates().find(item=>item.id===id);if(!f)return;inspectedFacility=id;
  document.querySelectorAll('[data-inspect]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.inspect===id)));
  $('candidate-detail').innerHTML=`<div class="detail-photo"><img src="${photo(f)}" alt="시설 대표 이미지"><span>대표 이미지 · 해당 시설의 실제 사진 아님</span></div><div class="detail-content"><div class="eyebrow">FACILITY DETAILS</div><h3>${esc(f.name)}</h3><div class="detail-tags"><span class="pill">정상운영 · 예시</span><span class="pill">${esc(sport)}</span><span class="pill">실내시설 · 예시</span></div><dl class="result-definition"><dt>소재지</dt><dd>${esc(region)} ${esc(f.district)} · 상세주소 미제공</dd><dt>시설 유형</dt><dd>생활체육시설 · 시안 예시</dd><dt>지원 종목</dt><dd>${f.sports.map(esc).join(' · ')}</dd><dt>종목 연결 근거</dt><dd>${esc(f.basis)} · 예시</dd><dt>운영기관 / 연락처</dt><dd>자료 미제공</dd><dt>면적 / 수용인원</dt><dd>자료 미제공 · 강좌 정원과 별도</dd></dl><div class="transport-detail"><h4>인접 대중교통</h4><p>이 시안에는 실제 정류장 정보가 연결되지 않았습니다.</p><small>실제 화면은 시설 좌표와 자료 수록 여부를 확인해 정류장 또는 확인 불가 사유를 표시합니다.</small></div><p class="note">이용 시간·대관 가능 여부는 시설 확인이 필요합니다.</p><label class="detail-select"><input id="detail-check" type="checkbox" ${selected.has(id)?'checked':''}><span>이 시설을 계획서에 포함하기</span></label></div>`;
  $('detail-check').onchange=e=>{e.target.checked?selected.add(id):selected.delete(id);updateSelection();};
}
function renderCandidates(){const rows=candidates();$('candidate-count').textContent=rows.length+'곳';$('facility-list').innerHTML=rows.map(f=>`<article class="pick-card"><button type="button" class="inspect-button" data-inspect="${f.id}" aria-pressed="false"><img src="${photo(f)}" alt="대표 시설 이미지"><span><b>${esc(f.name)}</b><small>${esc(region)} · ${esc(f.district)}</small><small>${esc(sport)} · 상세정보 보기 →</small></span></button><label class="pick-check"><input type="checkbox" value="${f.id}" ${selected.has(f.id)?'checked':''}><span>계획서에 포함</span></label></article>`).join('')||'<p class="note">연결 근거가 있는 시설이 없습니다. 종목이나 지역을 변경하세요.</p>';document.querySelectorAll('[data-inspect]').forEach(b=>b.onclick=()=>inspectCandidate(b.dataset.inspect));$('candidate-detail').hidden=!rows.length;if(rows.length)inspectCandidate(rows.some(f=>f.id===inspectedFacility)?inspectedFacility:rows[0].id);updateSelection();}
function renderConfirmed(){$('confirmed').innerHTML=`<div class="panel-head"><h3>확정한 시설 ${confirmed.length}곳</h3><button id="reselect">시설 재선택</button></div>`+confirmed.map(f=>`<div class="confirmed-row"><img src="${photo(f)}" alt="대표 이미지"><div><b>${esc(f.name)}</b><p class="note">${esc(region)} · ${esc(sport)} · ${f.basis}</p></div></div>`).join('');$('reselect').onclick=()=>{$('candidates').hidden=false;$('confirmed').hidden=true;$('details').hidden=true;selected=new Set(confirmed.map(f=>f.id));confirmed=[];stage(1);renderCandidates();};}
$('region').onchange=e=>setRegion(e.target.value);$('region-buttons').onclick=e=>{if(e.target.dataset.region)setRegion(e.target.dataset.region);};
$('start').onclick=()=>{started=true;$('builder').hidden=false;$('selection-scope').textContent=region;if(confirmed.length)selected=new Set(confirmed.map(f=>f.id));confirmed=[];$('confirmed').hidden=true;$('details').hidden=true;$('candidates').hidden=!sport;if(sport)renderCandidates();stage(1);$('builder').scrollIntoView({behavior:'smooth',block:'start'});$('sport').focus({preventScroll:true});};
$('sport').onchange=e=>{sport=e.target.value;selected.clear();confirmed=[];$('candidates').hidden=!sport;$('confirmed').hidden=true;$('details').hidden=true;stage(1);renderCandidates();};
$('facility-list').onchange=e=>{if(e.target.type!=='checkbox')return;e.target.checked?selected.add(e.target.value):selected.delete(e.target.value);updateSelection();};
$('change-region').onclick=$('back-region').onclick=()=>{$('details').hidden=true;stage(0);$('overview').scrollIntoView({block:'start'});};
$('confirm').onclick=()=>{confirmed=candidates().filter(f=>selected.has(f.id));if(!confirmed.length)return;$('candidates').hidden=true;$('confirmed').hidden=false;$('details').hidden=false;renderConfirmed();stage(2);$('details').scrollIntoView({behavior:'smooth',block:'start'});};
function renderResult(r){const v=r.values;$('result-heading').textContent=v.name;$('result-content').innerHTML=`<p class="muted">프로그램 설계안 · ${esc(r.created)} · 실제 개설·대관 확정 전</p><div class="result-block"><h3>설계 근거 · ${esc(r.region)} 이용현황</h3><div class="result-kpis"><div>이용 시설<strong>${fmt(r.metrics[0])}개</strong></div><div>개설 강좌<strong>${fmt(r.metrics[1])}건</strong></div><div>신청인원 합계<strong>${fmt(r.metrics[2])}명</strong></div></div><p class="note">관측기간 2020.01–2026.08 · 스포츠강좌이용권 이용현황 정보<br>개설월별 합계이며 고유 이용자 수가 아닙니다. 시안 수치는 예시입니다.</p><p>선택 종목: <b>${esc(r.sport)}</b> · 종목 신청인원: <b>${fmt(r.sports.find(s=>s[0]===r.sport)?.[1]||0)}명</b></p><p class="note">종목별 상위 현황: ${r.sports.map(([s,n])=>esc(s)+' '+fmt(n)+'명').join(' / ')}</p></div><div class="result-block"><h3>선택 시설 ${r.facilities.length}곳</h3>${r.facilities.map(f=>`<p>${esc(f.name)} · ${esc(r.region)} ${esc(f.district)} · ${esc(f.basis)}</p>`).join('')}</div><div class="result-block"><h3>운영 계획</h3><dl class="result-definition"><dt>모집인원</dt><dd>시설당 ${fmt(v.capacity)}명 · 전체 ${fmt(v.capacity*r.facilities.length)}명</dd><dt>수강료</dt><dd>${Number(v.fee)===0?'무료':fmt(v.fee)+'원 / 1인 / '+esc(v.feeUnit)}</dd><dt>대상</dt><dd>${esc(v.target||'미정')}</dd><dt>운영기간</dt><dd>${esc(v.start||'미정')} ~ ${esc(v.end||'미정')}</dd><dt>프로그램 설명</dt><dd>${esc(v.description)}</dd></dl></div>`;}
$('program-form').onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(new FormData(e.target));if(!confirmed.length){$('form-error').textContent='시설을 먼저 확정해 주세요.';return;}if(!values.name.trim()||!values.description.trim()){$('form-error').textContent='프로그램명과 설명을 입력해 주세요.';return;}if(values.start&&values.end&&values.end<values.start){$('form-error').textContent='종료일은 시작일 이후로 입력해 주세요.';return;}activeResult={region,sport,facilities:structuredClone(confirmed),metrics:[...regions[region].metrics],sports:structuredClone(regions[region].sports),values,created:new Date().toLocaleString('ko-KR')};renderResult(activeResult);e.target.reset();$('form-error').textContent='';started=false;selected.clear();confirmed=[];sport='';$('sport').value='';region='전국';$('builder').hidden=true;$('details').hidden=true;$('candidates').hidden=true;$('confirmed').hidden=true;stage(0);refreshDashboard();$('result-dialog').showModal();};
$('result-dialog').addEventListener('close',()=>{activeResult=null;$('result-content').replaceChildren();$('result-heading').textContent='프로그램 설계안';$('share-message').value='';$('recipient-label').querySelector('input').value='';});
document.querySelectorAll('[data-close]').forEach(b=>b.onclick=()=>$(b.dataset.close).close());
$('print').onclick=()=>window.print();
function share(channel){if(!activeResult)return;$('share-heading').textContent=channel+' · 내용 확인';$('recipient-label').hidden=channel==='카카오톡 보내기';$('share-message').value=`[프로그램 설계안]\n${activeResult.values.name}\n${activeResult.region} · ${activeResult.sport}\n${activeResult.facilities.map(f=>f.name).join(', ')}\n시설당 ${activeResult.values.capacity}명\n수강료 ${fmt(activeResult.values.fee)}원 / ${activeResult.values.feeUnit}`;$('share-help').textContent=channel==='문자 보내기'?'발신번호 등록과 문자 서비스 연동 후 실제 발송할 수 있습니다.':'저장 링크 없이 요약 텍스트를 공유하는 방식입니다. 실제 카카오 연동은 별도이며 시안에서는 전송하지 않습니다.';$('share-dialog').showModal();}
$('sms').onclick=()=>share('문자 보내기');$('kakao').onclick=()=>share('카카오톡 보내기');
function showPage(page){document.querySelectorAll('nav [data-page]').forEach(b=>b.classList.toggle('active',b.dataset.page===page));['design','programs','facilities'].forEach(p=>$(p+'-page').hidden=p!==page);$('page-title').textContent={design:'프로그램 설계',programs:'프로그램 현황',facilities:'시설 현황'}[page];$('page-description').textContent={design:'지역의 이용현황을 살펴보고, 시설과 운영 조건을 담은 프로그램을 설계하세요.',programs:'자료에 등록된 프로그램을 조회합니다.',facilities:'시설의 기본정보와 종목 연결 근거를 확인합니다.'}[page];if(page==='design')map?.resize();if(page==='programs')renderPrograms();if(page==='facilities')renderFacilities();}
document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>showPage(b.dataset.page));
function renderPrograms(){$('programs-page').innerHTML=`<div id="program-register" class="listing" style="margin-top:18px"><section class="panel filter"><h3>검색 조건</h3><label>지역<select><option>서울</option></select></label><label>종목<select><option>농구</option></select></label><label>프로그램명<input placeholder="프로그램 검색"></label><p class="note">조회 화면의 배치 시안입니다.</p></section><section class="panel"><div class="panel-head"><h2>등록 프로그램</h2><span class="pill">공공체육시설 프로그램 자료</span></div><div class="cards">${facilityBase.slice(0,3).map((f,i)=>`<article class="facility-card"><img src="${photo(f)}" alt="대표 이미지"><h3>${['청소년 농구 기초','주말 농구 교실','성인 농구 입문'][i]}</h3><p>${f.name}</p><p class="note">농구 · 월·수 · 50,000원/월<br>예시 자료 · 현재 모집 여부 별도 확인</p></article>`).join('')}</div><div class="table-wrap"><table><thead><tr><th>프로그램명</th><th>시설</th><th>지역</th><th>수강료</th></tr></thead><tbody>${facilityBase.slice(0,3).map(f=>`<tr><td>농구 기초 교실</td><td>${f.name}</td><td>서울</td><td>50,000원 / 월</td></tr>`).join('')}</tbody></table></div></section></div>`; }
function renderFacilities(){$('facilities-page').innerHTML=`<div class="split"><section class="panel"><div class="panel-head"><h2>시설 목록</h2><span class="pill">종목 연결 근거 표시</span></div>${facilityBase.map(f=>`<button class="facility-row full" data-facility="${f.id}" style="grid-template-columns:90px 1fr;text-align:left"><img src="${photo(f)}" alt="대표 이미지" style="width:90px"><span>${f.name}<small>서울 · ${f.district} · 정상운영</small><small>${f.sports.join(' · ')}</small></span></button>`).join('')}</section><section class="panel" id="facility-detail"></section></div>`;const detail=id=>{const f=facilityBase.find(x=>x.id===id);$('facility-detail').innerHTML=`<h2>시설 상세 정보</h2><img src="${photo(f)}" alt="대표 이미지" style="width:100%;max-height:230px;object-fit:cover;border-radius:5px;margin:18px 0"><h3>${f.name}</h3><p class="note">대표 이미지 · 실제 시설 사진 아님</p><dl class="result-definition"><dt>지역</dt><dd>서울 · ${f.district}</dd><dt>운영상태</dt><dd>정상운영 · 자료 기준</dd><dt>종목</dt><dd>${f.sports.join(', ')}</dd><dt>연결 근거</dt><dd>${f.basis}</dd></dl><div class="insight"><b>인접 대중교통</b><p>좌표·수록 범위에 따라 연결된 정류장을 표시합니다. 자료가 없으면 확인 불가 사유를 안내합니다.</p></div><p class="note">시설 수용인원과 강좌 모집인원은 별도입니다. 실제 개설 가능 여부는 시설에 확인해야 합니다.</p>`;};document.querySelectorAll('[data-facility]').forEach(b=>b.onclick=()=>detail(b.dataset.facility));detail('a');}
refreshDashboard();
fetch('provinces.json').then(r=>r.json()).then(data=>{geo=data;echarts.registerMap('review-provinces',geo);map=echarts.init($('map'));drawMap();new ResizeObserver(()=>map.resize()).observe($('map'));}).catch(()=>{$('map').innerHTML='<p class="note">지도를 불러오지 못했습니다. 아래 지역 버튼을 사용하세요.</p>';});
